# -*- coding: utf-8 -*-
from ._helpers import intro, schema, fall, mc

KURS = dict(
    id="k14", gebiet="eu", titel="Die Durchsetzungsrichtlinie 2004/48/EG", untertitel="Auskunft, Beweise, Eilrechtsschutz, Sanktionen und Kosten – für alle Schutzrechte",
    farbe="#8b3fb2", icon="hammer",
    beschreibung="Woher §§ 18 bis 19c MarkenG kommen: die Richtlinie 2004/48/EG im Wortlaut, ihre Umsetzung in MarkenG, PatG, GebrMG, DesignG, UrhG, HalblSchG und SortSchG, und die EuGH-Rechtsprechung zu Auskunft, Bankgeheimnis, Mittelspersonen, Schadensersatz und Patentanwaltskosten.",
    kapitel=[
        dict(id="k14a", titel="Zwei Richtlinien, ein Muster in sieben Gesetzen", einheiten=[
            intro("k14a-0", "Was die Durchsetzungsrichtlinie regelt",
                  "Die **Markenrechtsrichtlinie** sagt, was eine Marke ist und wann sie verletzt wird. Die **Durchsetzungsrichtlinie 2004/48/EG** (Enforcement-Richtlinie) sagt, wie der Inhaber eine Verletzung *durchsetzt* – und zwar für **alle** Rechte des geistigen Eigentums gleich: Marken, Patente, Gebrauchsmuster, Designs, Urheberrechte, Sorten, Halbleiter (Art. 1, 2). Sie verlangt von den Mitgliedstaaten Maßnahmen zur Beweisbeschaffung (Art. 6, 7), ein Auskunftsrecht (Art. 8), einstweilige Maßnahmen (Art. 9), Rückruf und Vernichtung (Art. 10), Unterlassungsanordnungen auch gegen Mittelspersonen (Art. 11), Schadensersatz (Art. 13), Kostenerstattung (Art. 14) und Urteilsveröffentlichung (Art. 15). Alles muss **fair, wirksam, verhältnismäßig und abschreckend** sein und darf nicht missbraucht werden (Art. 3). Deutschland hat die Richtlinie – zwei Jahre zu spät – mit dem **Durchsetzungsgesetz vom 7.7.2008** (in Kraft seit 1.9.2008) umgesetzt. Im MarkenG sind das § 18 Abs. 2, § 19 Abs. 2, §§ 19a bis 19c und die dreifache Schadensberechnung in § 14 Abs. 6; die Dringlichkeitsvermutung des § 140 Abs. 3 kam erst 2019 mit dem MaMoG hinzu.",
                  concepts=["durchsetzungsrl", "markenrl"], norms=["Art. 1 DurchsetzungsRL", "Art. 2 DurchsetzungsRL", "Art. 3 DurchsetzungsRL", "§ 18", "§ 19"]),
            intro("k14a-1", "Die Umsetzungstabelle: Artikel → Gesetz",
                  "Das Durchsetzungsgesetz war ein **Artikelgesetz**: Dieselben Vorschriften wurden in jedes Schutzrechtsgesetz eingefügt, in derselben Reihenfolge und fast wortgleich. Wer § 19 MarkenG kennt, kennt auch § 140b PatG, § 24b GebrMG, § 46 DesignG, § 101 UrhG und § 37b SortSchG; das HalblSchG verweist in § 9 Abs. 2 einfach auf das GebrMG. Die Tabelle zeigt für jeden Artikel der Richtlinie die umsetzende Norm in allen sieben Gesetzen und daneben das allgemeine Recht (ZPO, BGB), das die Richtlinie dort erfüllt, wo die Spezialgesetze schweigen (Eilverfahren, Arrest, Kosten). Lies sie zeilenweise: **Art. 8 = Auskunft**, **Art. 6/7 = Vorlage und Besichtigung**, **Art. 9 Abs. 2 = Sicherung**, **Art. 10 = Vernichtung und Rückruf**, **Art. 13 = Schadensersatz**, **Art. 14 = Kosten**, **Art. 15 = Urteilsbekanntmachung**.",
                  concepts=["durchsetzungsrl", "vernichtung_auskunft"], norms=["Art. 8 DurchsetzungsRL", "Art. 10 DurchsetzungsRL", "Art. 13 DurchsetzungsRL", "Art. 14 DurchsetzungsRL"],
                  distinctions=["d_durchsetzungsrl_umsetzung"]),
            schema("k14a-2", "Prüfungsschema: Durchsetzung einer Markenverletzung", "schema_durchsetzung",
                   "Vom Verdacht bis zur Vollstreckung, geordnet nach den Artikeln der Richtlinie; jeder Punkt nennt die MarkenG-Norm."),
            fall("k14a-3", "Der doppelte Lizenzsatz",
                 "Das Recht eines Mitgliedstaats erlaubt dem Rechtsinhaber, statt des konkreten Schadens pauschal das **Doppelte** der angemessenen Lizenzgebühr zu verlangen, ohne einen tatsächlichen Schaden nachzuweisen. Ein Verletzer meint, das sei ein von Art. 13 DurchsetzungsRL verbotener Strafschadensersatz.",
                 "Verstößt die nationale Regelung gegen die Durchsetzungsrichtlinie?", False,
                 ["**Nein!** Die Richtlinie ist nach Art. 2 Abs. 1 eine **Mindestharmonisierung**: Instrumente, die für den Rechtsinhaber günstiger sind, bleiben unberührt. Art. 13 verlangt „angemessenen Schadensersatz“ und erlaubt in Abs. 1 lit. b eine Pauschale auf Grundlage von „mindestens“ der hypothetischen Lizenzgebühr.",
                  "Erwägungsgrund 26 will keine *Verpflichtung* zu Strafschadensersatz einführen, verbietet ihn aber nicht (EuGH OTK, C-367/15). Deutschland hat diese Option nicht genutzt: § 14 Abs. 6 gewährt die einfache Lizenzanalogie; der BGH lehnt Verletzerzuschläge im Markenrecht ab."],
                 merke="Die Durchsetzungsrichtlinie ist ein Boden, keine Decke: strenger darf der Mitgliedstaat immer sein.",
                 level=2, concepts=["durchsetzungsrl", "schadensersatz", "lizenzanalogie"], norms=["Art. 2 DurchsetzungsRL", "Art. 13 DurchsetzungsRL", "§ 14 Abs. 6"], cases=["eugh_otk"], step="step:schema_durchsetzung.4.3"),
            fall("k14a-4", "Firma ohne Marke",
                 "Die „Bergmann Fahrräder GmbH“ hat keine Marke eingetragen, führt ihren Namen aber seit Jahren im geschäftlichen Verkehr (§ 5 Abs. 2 MarkenG). Ein Konkurrent vertreibt Räder unter „Bergmann Bikes“. Die GmbH will Auskunft über den Lieferanten der Räder nach § 19 MarkenG.",
                 "Ist der Auskunftsanspruch nach § 19 auch bei Verletzung eines bloßen Unternehmenskennzeichens eröffnet?", True,
                 ["**Ja!** § 19 Abs. 1 gilt „in den Fällen der §§ 14, 15 und 17“, also auch bei Verletzung einer geschäftlichen Bezeichnung nach § 15. Das entspricht Art. 2 Abs. 1 DurchsetzungsRL: Erfasst ist jede Verletzung von Rechten des geistigen Eigentums, die im Unionsrecht **oder im nationalen Recht** vorgesehen sind – Unternehmenskennzeichen und Benutzungsmarken eingeschlossen.",
                  "Die Richtlinie harmonisiert also mehr Rechte als die MarkenRL (die nur Registermarken erfasst). Erwägungsgrund 13 erlaubt den Mitgliedstaaten sogar, die Instrumente auf den unlauteren Wettbewerb zu erstrecken."],
                 merke="Die Durchsetzungsrichtlinie fragt nicht, woher das Recht kommt, sondern nur, ob es eines ist.",
                 level=1, concepts=["durchsetzungsrl", "geschaeftliche_bezeichnung"], norms=["§ 19 Abs. 1", "§ 15", "Art. 2 DurchsetzungsRL"], step="step:schema_durchsetzung.1"),
            mc("k14a-5", "Gewerbliches Ausmaß",
               "Was bedeutet „gewerbliches Ausmaß“ im Sinne der Durchsetzungsrichtlinie (Erwägungsgrund 14)?",
               ["Jede Handlung im geschäftlichen Verkehr im Sinne von § 14 Abs. 2 MarkenG", "Handlungen zur Erlangung eines unmittelbaren oder mittelbaren wirtschaftlichen oder kommerziellen Vorteils; gutgläubige Endverbraucher sind in der Regel nicht erfasst", "Nur Handlungen von Kaufleuten im Sinne des HGB", "Nur Handlungen mit einem Umsatz über 10.000 Euro"], 1,
               ["Erwägungsgrund 14 definiert: Rechtsverletzungen in gewerblichem Ausmaß werden **zwecks Erlangung eines unmittelbaren oder mittelbaren wirtschaftlichen oder kommerziellen Vorteils** vorgenommen; Handlungen gutgläubiger Endverbraucher fallen in der Regel heraus. Das Merkmal ist Voraussetzung der Drittauskunft (§ 19 Abs. 2), der Vorlage von Bank-, Finanz- und Handelsunterlagen (§ 19a Abs. 1 S. 2) und der Sicherung von Schadensersatz (§ 19b).",
                "Es ist etwas anderes als das Handeln „im geschäftlichen Verkehr“ (§ 14 Abs. 2), das die Verletzung selbst betrifft: Ein Spediteur, der Fälschungen lagert, verletzt die Marke nicht, hat die Ware aber in gewerblichem Ausmaß in Besitz und schuldet deshalb Auskunft."],
               level=2, concepts=["gewerbliches_ausmass", "geschaeftlicher_verkehr"], norms=["§ 19 Abs. 2", "§ 19a", "§ 19b", "Art. 8 DurchsetzungsRL"], step="step:schema_durchsetzung.2.2"),
            fall("k14a-6", "Der Abmahn-Zessionar",
                 "Die M-Ltd. erwirbt von Filmproduzenten die Verwertungsrechte an Erotikfilmen, wertet die Filme aber nicht aus, sondern lässt in Tauschbörsen IP-Adressen sammeln und verlangt vom Internetprovider T Auskunft über die Anschlussinhaber, um sie abzumahnen.",
                 "Kann M als Rechtsinhaberin die Auskunft nach Art. 8 DurchsetzungsRL verlangen?", True,
                 ["**Ja, grundsätzlich!** Auch ein Zessionar, der die Rechte nur erworben hat, um Verletzer abzumahnen, ist **Inhaber** im Sinne von Art. 4 lit. a und kann die Maßnahmen der Richtlinie beantragen (EuGH Mircom, C-597/19). Die Richtlinie knüpft an die Inhaberschaft an, nicht an die Art der Verwertung.",
                  "Das Gericht muss aber nach Art. 3 Abs. 2 prüfen, ob der Antrag **begründet und verhältnismäßig** ist und ob ein **Rechtsmissbrauch** vorliegt, etwa wenn es nur um Vergleichszahlungen statt um Rechtsdurchsetzung geht. In Deutschland läuft die Provider-Auskunft über § 19 Abs. 9 MarkenG bzw. § 101 Abs. 9 UrhG mit richterlicher Anordnung."],
                 merke="Inhaber ist, wer das Recht hat – der Missbrauch wird an der Verhältnismäßigkeit geprüft, nicht an der Inhaberschaft.",
                 level=3, concepts=["durchsetzungsrl", "aktivlegitimation", "drittauskunft"], norms=["Art. 3 DurchsetzungsRL", "Art. 4 DurchsetzungsRL", "Art. 8 DurchsetzungsRL", "§ 19 Abs. 9"], cases=["eugh_mircom"], step="step:schema_durchsetzung.7"),
            fall("k14a-7", "Der Lizenznehmer klagt selbst",
                 "L ist ausschließliche Lizenznehmerin der Marke „VELOX“ für Deutschland. Ein Verletzer vertreibt Plagiate. L fordert die Markeninhaberin I schriftlich auf, Klage zu erheben; I lässt drei Monate verstreichen, ohne zu reagieren.",
                 "Kann L jetzt ohne Zustimmung von I Verletzungsklage erheben?", True,
                 ["**Ja!** Nach § 30 Abs. 3 S. 1 kann der Lizenznehmer Verletzungsklage nur mit Zustimmung des Inhabers erheben. Der Inhaber einer **ausschließlichen** Lizenz darf aber ohne Zustimmung klagen, wenn der Markeninhaber nach förmlicher Aufforderung nicht innerhalb angemessener Frist selbst Klage erhebt (§ 30 Abs. 3 S. 2).",
                  "Das ist die deutsche Antwort auf Art. 4 lit. b DurchsetzungsRL, der Lizenznehmern die Antragsbefugnis „soweit nach dem anwendbaren Recht zulässig“ einräumt – die Richtlinie überlässt das Wie dem nationalen Recht. Jeder Lizenznehmer kann außerdem der Klage des Inhabers beitreten, um eigenen Schaden geltend zu machen (§ 30 Abs. 4)."],
                 merke="Ausschließlicher Lizenznehmer: erst auffordern, dann selbst klagen.",
                 level=2, concepts=["lizenz", "aktivlegitimation"], norms=["§ 30 Abs. 3", "§ 30 Abs. 4", "Art. 4 DurchsetzungsRL"], step="step:schema_durchsetzung.1"),
            mc("k14a-8", "Wie kam die Richtlinie ins MarkenG?",
               "Welche Aussage zur Umsetzung der Durchsetzungsrichtlinie in Deutschland ist richtig?",
               ["Sie wurde fristgerecht 2006 durch das MarkenG-Änderungsgesetz umgesetzt", "Sie wurde durch das Gesetz zur Verbesserung der Durchsetzung von Rechten des geistigen Eigentums vom 7.7.2008 mit Wirkung zum 1.9.2008 umgesetzt, als Artikelgesetz für MarkenG, PatG, GebrMG, DesignG, UrhG, HalblSchG und SortSchG", "Sie gilt als Verordnung unmittelbar und musste nicht umgesetzt werden", "Sie wurde 2019 zusammen mit der MarkenRL durch das MaMoG umgesetzt"], 1,
               ["Die Umsetzungsfrist des Art. 20 endete am **29.4.2006**; Deutschland setzte die Richtlinie erst mit dem **Durchsetzungsgesetz vom 7.7.2008** (BGBl. I S. 1191) um, in Kraft seit **1.9.2008**. Es fügte in alle Schutzrechtsgesetze gleichlautende Vorschriften ein: § 18 Abs. 2 (Rückruf), § 19 Abs. 2 (Drittauskunft), §§ 19a bis 19c, § 14 Abs. 6 S. 2, 3 (dreifache Schadensberechnung) im MarkenG.",
                "Das MaMoG 2019 betraf die MarkenRL (EU) 2015/2436, nicht die Durchsetzungsrichtlinie. Richtlinien wirken nicht unmittelbar zwischen Privaten; bis zur Umsetzung galt richtlinienkonforme Auslegung des alten Rechts (§ 242 BGB, § 809 BGB)."],
               level=1, concepts=["durchsetzungsrl", "richtlinienkonforme_auslegung"], norms=["Art. 20 DurchsetzungsRL", "§ 18", "§ 19"]),
        ]),
        dict(id="k14b", titel="Aufklärung: Auskunft, Vorlage, Sicherung (Art. 6 bis 9)", einheiten=[
            intro("k14b-0", "Drei Aufklärungsansprüche, drei Fragen",
                  "Bevor der Inhaber klagen kann, muss er wissen, **wer** verletzt, **woher** die Ware kommt und **wohin** sie geht – und ob sich eine Klage lohnt. Dafür gibt die Richtlinie drei Werkzeuge, die das MarkenG in §§ 19, 19a, 19b nebeneinander stellt: Die **Auskunft** (§ 19 = Art. 8) fragt „woher und wohin?“ und richtet sich bei offensichtlicher Verletzung oder nach Klageerhebung auch gegen Dritte in der Lieferkette. **Vorlage und Besichtigung** (§ 19a = Art. 6, 7) fragen „stimmt der Verdacht?“ und setzen nur hinreichende Wahrscheinlichkeit voraus. Die **Sicherung von Schadensersatz** (§ 19b = Art. 9 Abs. 2) fragt „kann er zahlen?“. Alle drei stehen unter dem Vorbehalt der Verhältnismäßigkeit (Art. 3 Abs. 2), und alle drei lassen sich per einstweiliger Verfügung durchsetzen – unter verschieden strengen Bedingungen.",
                  concepts=["drittauskunft", "vorlage_besichtigung", "sicherung_schadensersatz"], norms=["§ 19", "§ 19a", "§ 19b", "Art. 8 DurchsetzungsRL", "Art. 6 DurchsetzungsRL", "Art. 9 DurchsetzungsRL"],
                  distinctions=["d_aufklaerungsansprueche"]),
            fall("k14b-1", "Der Kontoinhaber hinter dem Parfüm",
                 "Coty kauft auf einer Auktionsplattform ein offensichtlich gefälschtes Parfüm „Davidoff Hot Water“ und zahlt auf ein Konto bei der Stadtsparkasse. Der Verkäufer ist nicht zu ermitteln. Coty verlangt von der Sparkasse Name und Anschrift des Kontoinhabers; die Sparkasse beruft sich auf das Bankgeheimnis.",
                 "Muss die Sparkasse Auskunft erteilen?", True,
                 ["**Ja!** Die Sparkasse hat in gewerblichem Ausmaß eine für die rechtsverletzende Tätigkeit genutzte Dienstleistung erbracht (§ 19 Abs. 2 S. 1 Nr. 3 = Art. 8 Abs. 1 lit. c DurchsetzungsRL); die Verletzung ist offensichtlich. Zwar nimmt § 19 Abs. 2 S. 1 Halbs. 2 Zeugnisverweigerungsberechtigte aus, und § 383 Abs. 1 Nr. 6 ZPO schützt das Bankgeheimnis.",
                  "Der EuGH hat aber entschieden, dass Art. 8 Abs. 3 lit. e einer Regelung entgegensteht, die einer Bank erlaubt, **unbegrenzt und bedingungslos** die Auskunft zu verweigern (Coty/Stadtsparkasse, C-580/13). Der BGH legt § 19 Abs. 2 deshalb richtlinienkonform aus: Kein Bankgeheimnis, wenn über das Konto der Kaufpreis für offensichtlich markenverletzende Ware abgewickelt wurde (Davidoff Hot Water II)."],
                 merke="Bankgeheimnis schlägt Markenschutz nicht pauschal – Art. 17 Abs. 2 GRCh will ausgeglichen, nicht ausgeschaltet werden.",
                 level=2, concepts=["drittauskunft", "richtlinienkonforme_auslegung"], norms=["§ 19 Abs. 2", "Art. 8 Abs. 3 lit. e DurchsetzungsRL"], cases=["eugh_coty_stadtsparkasse", "bgh_davidoff_hot_water_ii"], step="step:schema_durchsetzung.2.2"),
            fall("k14b-2", "E-Mail-Adresse des Uploaders",
                 "Ein Nutzer hat auf einer Videoplattform einen Kinofilm hochgeladen. Der Rechtsinhaber verlangt vom Plattformbetreiber nach dem Auskunftsanspruch die E-Mail-Adresse, die Telefonnummer und die IP-Adresse des Nutzers und stützt sich auf das Wort „Adressen“ in Art. 8 Abs. 2 lit. a DurchsetzungsRL.",
                 "Umfasst „Adressen“ im Sinne der Richtlinie auch E-Mail-Adresse, Telefonnummer und IP-Adresse?", False,
                 ["**Nein!** Der EuGH legt „Adressen“ nach gewöhnlichem Sprachgebrauch, Entstehungsgeschichte und Systematik eng aus: gemeint ist nur die **Postanschrift** (Constantin Film Verleih/YouTube, C-264/19). Auch § 19 Abs. 3 Nr. 1 MarkenG spricht von „Namen und Anschrift“.",
                  "Die Mitgliedstaaten dürfen weitergehende Auskunftsrechte vorsehen (Art. 8 Abs. 3 lit. a), müssen dann aber den Ausgleich zwischen Eigentumsschutz und Datenschutz wahren. Deutschland hat das für Verkehrsdaten getan: Auskunft nur nach richterlicher Anordnung (§ 19 Abs. 9; § 101 Abs. 9 UrhG)."],
                 merke="Adresse heißt Postanschrift; alles Digitale braucht eine eigene nationale Grundlage.",
                 level=2, concepts=["drittauskunft"], norms=["§ 19 Abs. 3", "§ 19 Abs. 9", "Art. 8 Abs. 2 lit. a DurchsetzungsRL"], cases=["eugh_constantin_film"], step="step:schema_durchsetzung.2.2"),
            fall("k14b-3", "Auskunft nach dem Urteil",
                 "N hat gegen A ein rechtskräftiges Urteil erstritten, das die Markenverletzung feststellt und A zur Unterlassung verurteilt. Auskunft hatte N damals nicht beantragt. Ein Jahr später erhebt N eine neue Klage allein auf Auskunft über Herkunft und Vertriebsweg der Ware.",
                 "Ist die gesonderte Auskunftsklage nach Abschluss des Verletzungsprozesses zulässig?", True,
                 ["**Ja!** Art. 8 Abs. 1 verlangt nur einen Antrag „im Zusammenhang mit einem Verfahren wegen Verletzung“. Der EuGH legt das weit aus: Das Auskunftsrecht kann auch in einem **gesonderten Verfahren nach rechtskräftigem Abschluss** des Verletzungsprozesses geltend gemacht werden, weil es der wirksamen Ausübung des Grundrechts auf geistiges Eigentum dient (NEW WAVE CZ/ALLTOYS, C-427/15).",
                  "Im deutschen Recht ist § 19 ohnehin ein selbständiger materieller Anspruch, der isoliert eingeklagt werden kann; die Verjährung richtet sich nach § 20."],
                 merke="Auskunft ist ein eigener Anspruch, kein Anhängsel der Unterlassungsklage.",
                 level=2, concepts=["drittauskunft", "vernichtung_auskunft"], norms=["§ 19 Abs. 1", "§ 20", "Art. 8 Abs. 1 DurchsetzungsRL"], cases=["eugh_new_wave"], step="step:schema_durchsetzung.2.2"),
            fall("k14b-4", "Auskunft im Eilverfahren",
                 "Beim Zoll wird eine Palette mit Fälschungen der Marke „ZENTRO“ entdeckt; das Zeichen ist identisch, die Ware eindeutig gefälscht. Die Inhaberin will sofort den Lieferanten erfahren, bevor die Spuren verwischt sind, und beantragt eine einstweilige Verfügung auf Auskunft.",
                 "Kann die Auskunft im Wege der einstweiligen Verfügung angeordnet werden?", True,
                 ["**Ja!** In Fällen **offensichtlicher Rechtsverletzung** kann die Auskunftspflicht nach § 19 Abs. 7 im Wege der einstweiligen Verfügung (§§ 935 bis 945 ZPO) angeordnet werden. Die Beschränkung auf offensichtliche Verletzungen rechtfertigt die Vorwegnahme der Hauptsache: Eine erteilte Auskunft lässt sich nicht rückgängig machen.",
                  "Bei identischem Zeichen und identischen Waren (§ 14 Abs. 2 Nr. 1) ist die Verletzung offensichtlich. Unionsrechtlich beruht das auf Art. 9 Abs. 1 DurchsetzungsRL in Verbindung mit dem Gebot wirksamer und schneller Rechtsbehelfe (Art. 3)."],
                 merke="Eilauskunft nur, wenn die Verletzung auf der Hand liegt – dann aber sofort.",
                 level=1, concepts=["drittauskunft", "einstweilige_verfuegung"], norms=["§ 19 Abs. 7", "Art. 9 DurchsetzungsRL"], step="step:schema_durchsetzung.3"),
            fall("k14b-5", "Der Spediteur ohne Klage",
                 "Spediteur S hat für einen Händler gewerblich Sportschuhe eingelagert, die mit einem der Marke „AIRLINE“ ähnlichen Zeichen versehen sind; ob Verwechslungsgefahr besteht, ist streitig. Die Markeninhaberin hat gegen den Händler noch keine Klage erhoben, verlangt aber von S Auskunft über den Absender der Ware.",
                 "Besteht der Auskunftsanspruch gegen S nach § 19 Abs. 2?", False,
                 ["**Nein!** Der Anspruch gegen Dritte besteht nur „in Fällen offensichtlicher Rechtsverletzung“ oder wenn der Inhaber gegen den Verletzer **Klage erhoben** hat (§ 19 Abs. 2 S. 1). Beides fehlt: Die Verwechslungsgefahr ist streitig, also nicht offensichtlich, und eine Klage gegen den Händler gibt es nicht.",
                  "S ist zwar Dritter im Sinne von Nr. 1 (Besitz rechtsverletzender Ware in gewerblichem Ausmaß). Die Richtlinie verlangt aber ohnehin nur einen Anspruch „im Zusammenhang mit einem Verfahren“ (Art. 8 Abs. 1); die deutsche Fassung erweitert das um die offensichtliche Verletzung. Lösung für die Inhaberin: erst Klage gegen den Händler, dann Auskunft von S; das Gericht kann den Verletzungsprozess bis zur Auskunft aussetzen (§ 19 Abs. 2 S. 2)."],
                 merke="Drittauskunft braucht einen Anker: offensichtliche Verletzung oder anhängige Klage.",
                 level=2, concepts=["drittauskunft", "gewerbliches_ausmass"], norms=["§ 19 Abs. 2", "Art. 8 Abs. 1 DurchsetzungsRL"], step="step:schema_durchsetzung.2.2"),
            fall("k14b-6", "Besichtigung in der Fabrik",
                 "Die Inhaberin der Marke „TERRAFORM“ für Gartengeräte erfährt von einem Händler, dass F in seiner Fabrik Geräte mit dem Zeichen „TERRAFORM“ produziere; ein Foto eines Kartons liegt vor. F bestreitet alles und verweigert den Zutritt. Die Inhaberin will die Produktionshalle besichtigen und die Lieferlisten einsehen.",
                 "Kann sie Besichtigung und Vorlage verlangen, obwohl die Verletzung noch nicht feststeht?", True,
                 ["**Ja!** § 19a Abs. 1 (Art. 6, 7 DurchsetzungsRL) verlangt keine erwiesene Verletzung, sondern nur deren **hinreichende Wahrscheinlichkeit** – ein gewisser Grad an Wahrscheinlichkeit genügt (BGH Faxkarte zu § 809 BGB). Foto und Händleraussage reichen. Der Anspruch geht auf Vorlage von Urkunden und Besichtigung von Sachen in F's Verfügungsgewalt; bei gewerblichem Ausmaß auch auf Bank-, Finanz- und Handelsunterlagen (S. 2).",
                  "Praktisch wird er per einstweiliger Verfügung ohne Anhörung durchgesetzt (Abs. 3). Den Geheimnisschutz sichert das **Düsseldorfer Verfahren**: Ein zur Verschwiegenheit verpflichteter Sachverständiger besichtigt, sein Gutachten wird erst nach Anhörung von F freigegeben. Stellt sich heraus, dass keine Verletzung vorlag, schuldet die Inhaberin verschuldensunabhängig Schadensersatz (Abs. 5 = Art. 7 Abs. 4)."],
                 merke="§ 19a: Verdacht plus Verhältnismäßigkeit öffnet die Tür, der Sachverständige schützt die Geheimnisse.",
                 level=2, concepts=["vorlage_besichtigung", "gewerbliches_ausmass"], norms=["§ 19a", "Art. 6 DurchsetzungsRL", "Art. 7 DurchsetzungsRL"], cases=["bgh_faxkarte"], step="step:schema_durchsetzung.2.1"),
            mc("k14b-7", "§ 19a oder § 19b?",
               "Die Verletzung steht fest und der Verletzer ist zum Schadensersatz verurteilt; er gibt an, mittellos zu sein. Die Inhaberin vermutet verschobene Erlöse und will Einsicht in seine Bankunterlagen, um den Anspruch durchzusetzen. Welcher Anspruch passt?",
               ["§ 19a Abs. 1 S. 2: Vorlage von Bankunterlagen zur Begründung der Verletzung", "§ 19b Abs. 1: Vorlage von Bank-, Finanz- oder Handelsunterlagen zur Sicherung des Schadensersatzanspruchs bei gewerblichem Ausmaß", "§ 19 Abs. 3: Auskunft über Preise", "§ 18 Abs. 2: Rückruf"], 1,
               ["Hier geht es nicht mehr um den Nachweis der Verletzung (§ 19a), sondern um die **Durchsetzung des Schadensersatzes**: § 19b Abs. 1 gibt bei einer in gewerblichem Ausmaß begangenen Verletzung Anspruch auf Vorlage von Bank-, Finanz- oder Handelsunterlagen, wenn ohne sie die Erfüllung des Schadensersatzanspruchs fraglich ist. Das setzt Art. 9 Abs. 2 DurchsetzungsRL um.",
                "Die dort ebenfalls vorgesehene vorsorgliche Vermögensbeschlagnahme (Kontosperre) läuft in Deutschland über den **dinglichen Arrest** (§§ 916 ff. ZPO). Einstweilige Verfügung nach § 19b Abs. 3 nur, wenn der Schadensersatzanspruch offensichtlich besteht."],
               level=2, concepts=["sicherung_schadensersatz", "vorlage_besichtigung"], norms=["§ 19b", "§ 19a", "Art. 9 Abs. 2 DurchsetzungsRL"], step="step:schema_durchsetzung.2.3"),
            fall("k14b-8", "Verkehrsdaten ohne Richter",
                 "Die Inhaberin der Marke „NOVA-CELL“ stellt fest, dass unter einer bestimmten IP-Adresse ein Online-Shop mit Fälschungen betrieben wird. Sie verlangt vom Internetzugangsanbieter nach § 19 Abs. 2 Nr. 3 sofort Name und Anschrift des Anschlussinhabers, ohne ein Gericht einzuschalten.",
                 "Muss der Provider die Auskunft ohne richterliche Anordnung erteilen?", False,
                 ["**Nein!** Kann die Auskunft nur unter Verwendung von **Verkehrsdaten** (Zuordnung einer IP-Adresse zu einem Anschluss) erteilt werden, ist nach § 19 Abs. 9 eine vorherige **richterliche Anordnung** über die Zulässigkeit der Verwendung nötig, die der Verletzte beim Landgericht beantragt (Zivilkammer, Verfahren nach dem FamFG, Kosten trägt der Verletzte).",
                  "Das setzt Art. 8 Abs. 3 lit. e DurchsetzungsRL um (Vorbehalt des Datenschutzes) und die Vorgabe des EuGH, dass Eigentumsschutz und Datenschutz in ein angemessenes Gleichgewicht zu bringen sind (Promusicae, C-275/06). § 19 Abs. 10 stellt klar, dass Art. 10 GG (Fernmeldegeheimnis) eingeschränkt wird."],
                 merke="IP-Adresse zu Person: nur mit richterlichem Beschluss (§ 19 Abs. 9).",
                 level=3, concepts=["drittauskunft"], norms=["§ 19 Abs. 9", "§ 19 Abs. 10", "Art. 8 Abs. 3 lit. e DurchsetzungsRL"], cases=["eugh_promusicae"], step="step:schema_durchsetzung.2.2"),
            fall("k14b-9", "Die unberechtigte Besichtigung",
                 "Auf Antrag der Markeninhaberin M wird per einstweiliger Verfügung die Besichtigung des Lagers von B angeordnet und vollzogen. Der Sachverständige stellt fest: Die Ware trägt ein völlig anderes Zeichen, eine Verletzung liegt nicht vor. B verlangt Ersatz seiner Kosten und des Betriebsausfalls. M wendet ein, sie habe sorgfältig geprüft und treffe kein Verschulden.",
                 "Haftet M auch ohne Verschulden?", True,
                 ["**Ja!** Wenn keine Verletzung vorlag oder drohte, kann der vermeintliche Verletzer von demjenigen, der Vorlage oder Besichtigung begehrt hat, den Ersatz des ihm entstandenen Schadens verlangen (§ 19a Abs. 5). Die Norm ist **verschuldensunabhängig** und setzt Art. 7 Abs. 4 DurchsetzungsRL um („angemessener Ersatz“ bei Aufhebung oder wenn sich herausstellt, dass keine Verletzung vorlag).",
                  "Daneben gilt für die Vollziehung der einstweiligen Verfügung § 945 ZPO, ebenfalls verschuldensunabhängig. Wer das scharfe Schwert der Besichtigung zieht, trägt das Risiko des Irrtums."],
                 merke="Besichtigung auf eigenes Risiko: Irrtum kostet, Verschulden ist egal.",
                 level=2, concepts=["vorlage_besichtigung", "einstweilige_verfuegung"], norms=["§ 19a Abs. 5", "Art. 7 Abs. 4 DurchsetzungsRL"], step="step:schema_durchsetzung.2.1"),
        ]),
        dict(id="k14c", titel="Eilrechtsschutz, Sanktionen, Mittelspersonen, Kosten (Art. 9 bis 15)", einheiten=[
            fall("k14c-1", "Dringlichkeit ohne Glaubhaftmachung",
                 "Die Inhaberin der Marke „LUMINA“ erfährt am 3. Mai von Plagiaten und beantragt am 20. Mai eine einstweilige Unterlassungsverfügung. Der Antragsgegner rügt, sie habe nicht dargelegt, warum die Sache eilig sei.",
                 "Muss die Inhaberin den Verfügungsgrund (Dringlichkeit) darlegen und glaubhaft machen?", False,
                 ["**Nein!** Zur Sicherung der Unterlassungsansprüche aus dem MarkenG können einstweilige Verfügungen auch **ohne Darlegung und Glaubhaftmachung** der Voraussetzungen der §§ 935, 940 ZPO erlassen werden (§ 140 Abs. 3): Die Dringlichkeit wird vermutet. Die Vorschrift kam erst mit dem MaMoG 2019 ins Gesetz (Vorbild § 12 Abs. 1 UWG) und geht über Art. 9 Abs. 1 lit. a DurchsetzungsRL hinaus, der nur schnelle einstweilige Maßnahmen verlangt, aber keine Vermutung vorschreibt.",
                  "Die Vermutung ist widerlegt, wenn der Antragsteller durch eigenes Zögern zeigt, dass es ihm nicht eilig ist; die Oberlandesgerichte setzen meist etwa einen Monat ab Kenntnis an. 17 Tage sind unproblematisch. Für Auskunft (§ 19 Abs. 7) und Vorlage (§ 19a Abs. 3) gilt die Vermutung nicht."],
                 merke="§ 140 Abs. 3: Dringlichkeit wird vermutet – wer trödelt, verliert sie.",
                 level=1, concepts=["einstweilige_verfuegung", "unterlassungsanspruch"], norms=["§ 140 Abs. 3", "Art. 9 DurchsetzungsRL"], step="step:schema_durchsetzung.3"),
            fall("k14c-2", "Die aufgehobene Verfügung",
                 "Auf Antrag der P erlässt das Landgericht eine einstweilige Unterlassungsverfügung gegen G; G stellt den Vertrieb ein und ruft die Ware zurück. Im Hauptsacheverfahren wird P's Marke wegen Bösgläubigkeit für nichtig erklärt, die Verfügung aufgehoben. G verlangt Ersatz des Vertriebsausfalls und der Rückrufkosten; P beruft sich darauf, sie habe die Nichtigkeit nicht vorhersehen können.",
                 "Hat G einen Schadensersatzanspruch, obwohl P kein Verschulden trifft?", True,
                 ["**Ja!** Erweist sich die einstweilige Verfügung als von Anfang an ungerechtfertigt, ist der Antragsteller nach § 945 ZPO zum Ersatz des Vollziehungsschadens verpflichtet – **verschuldensunabhängig**. Erfasst sind auch die Kosten eines Rückrufs, den G zur Befolgung der Verfügung durchführen musste.",
                  "Art. 9 Abs. 7 DurchsetzungsRL verlangt nur „angemessenen Ersatz“; der EuGH lässt zu, dass das nationale Gericht alle Umstände würdigt, etwa ob der Antragsgegner durch Markteintritt trotz laufenden Schutzrechts das Risiko selbst geschaffen hat (Bayer Pharma/Richter, C-688/17). § 945 ZPO geht darüber hinaus und ist als günstigere Regelung zulässig (Art. 2 Abs. 1)."],
                 merke="Wer die Verfügung vollzieht, haftet für sie – § 945 ZPO fragt nicht nach Schuld.",
                 level=3, concepts=["einstweilige_verfuegung", "boesglaeubigkeit"], norms=["§ 140 Abs. 3", "Art. 9 Abs. 7 DurchsetzungsRL", "Art. 2 DurchsetzungsRL"], cases=["eugh_bayer_richter"], step="step:schema_durchsetzung.3"),
            fall("k14c-3", "Rückruf aus dem Handel",
                 "Großhändler G hat 5.000 T-Shirts mit dem verletzenden Zeichen bereits an Einzelhändler ausgeliefert, die sie noch nicht verkauft haben. Die Markeninhaberin verlangt von G, die T-Shirts von den Einzelhändlern zurückzurufen.",
                 "Kann sie den Rückruf verlangen, obwohl G die Ware nicht mehr besitzt?", True,
                 ["**Ja!** Neben der Vernichtung der im Besitz oder Eigentum des Verletzers befindlichen Ware (§ 18 Abs. 1) kann der Inhaber den Verletzer auf **Rückruf** widerrechtlich gekennzeichneter Waren oder deren **endgültiges Entfernen aus den Vertriebswegen** in Anspruch nehmen (§ 18 Abs. 2). Der Anspruch erfasst gerade Ware, die der Verletzer schon weitergegeben hat.",
                  "Das setzt Art. 10 Abs. 1 lit. a und b DurchsetzungsRL um; nach Art. 10 Abs. 2 geschieht es auf Kosten des Verletzers. Grenze: Unverhältnismäßigkeit im Einzelfall unter Berücksichtigung der Interessen Dritter (§ 18 Abs. 3 = Art. 10 Abs. 3), etwa gutgläubiger Abnehmer. Verschulden ist nicht erforderlich."],
                 merke="Vernichtung trifft, was der Verletzer hat; Rückruf holt, was er schon weitergab.",
                 level=1, concepts=["vernichtung_auskunft"], norms=["§ 18 Abs. 2", "§ 18 Abs. 3", "Art. 10 DurchsetzungsRL"], step="step:schema_durchsetzung.4.2"),
            mc("k14c-4", "Vernichtung oder milderes Mittel?",
               "Ein Händler hat hochwertige Lederjacken importiert, an denen ein leicht entfernbares Anhängeetikett mit dem verletzenden Zeichen befestigt ist. Die Jacken selbst sind neutral. Die Markeninhaberin verlangt Vernichtung aller Jacken. Wie ist die Rechtslage?",
               ["Vernichtung ist stets zu gewähren, § 18 Abs. 1 kennt keine Ausnahme", "Der Vernichtungsanspruch ist ausgeschlossen, wenn er im Einzelfall unverhältnismäßig ist; hier genügt die Entfernung der Etiketten (§ 18 Abs. 3, Art. 10 Abs. 3 DurchsetzungsRL)", "Vernichtung kommt nur bei Verschulden in Betracht", "Der Händler kann die Jacken behalten, weil er sie bezahlt hat"], 1,
               ["Der Vernichtungsanspruch ist ausgeschlossen, wenn die Inanspruchnahme im Einzelfall **unverhältnismäßig** ist; dabei sind auch die berechtigten Interessen Dritter zu berücksichtigen (§ 18 Abs. 3). Das setzt Art. 10 Abs. 3 DurchsetzungsRL um: angemessenes Verhältnis zwischen Schwere der Verletzung und Abhilfemaßnahme. Lässt sich die Kennzeichnung ohne Weiteres entfernen, ist die Vernichtung wertvoller neutraler Ware unverhältnismäßig.",
                "Dann bleibt der Beseitigungsanspruch auf Entfernung der Kennzeichnung. Verschulden verlangt § 18 nicht; entscheidend sind Verletzung und Verhältnismäßigkeit. Beim Rückruf gilt dieselbe Grenze."],
               level=2, concepts=["vernichtung_auskunft", "durchsetzungsrl"], norms=["§ 18 Abs. 1", "§ 18 Abs. 3", "Art. 10 Abs. 3 DurchsetzungsRL", "Art. 3 DurchsetzungsRL"], step="step:schema_durchsetzung.4.2"),
            fall("k14c-5", "Lizenzanalogie und Rufschaden",
                 "Die Inhaberin einer bekannten Kosmetikmarke berechnet ihren Schaden nach der Lizenzanalogie. Zusätzlich verlangt sie Ersatz für den Imageschaden, weil die minderwertigen Fälschungen den Ruf der Marke beschädigt haben. Der Verletzer meint, mit der Wahl der Lizenzanalogie sei alles abgegolten.",
                 "Schließt die Wahl der Lizenzanalogie weitere Schadensposten aus?", False,
                 ["**Nein!** Art. 13 Abs. 1 lit. b DurchsetzungsRL erlaubt den Pauschalbetrag „auf der Grundlage von Faktoren wie **mindestens** dem Betrag der Vergütung“; die hypothetische Lizenzgebühr ist eine Untergrenze. Wer sie wählt, kann daneben Ersatz eines Schadens verlangen, den die Pauschale nicht abdeckt, insbesondere immateriellen Schaden (EuGH Liffers, C-99/15).",
                  "Im deutschen Recht (§ 14 Abs. 6) ist der Marktverwirrungs- und Rufschaden ein Vermögensschaden, der neben der Lizenzanalogie ersatzfähig ist, soweit er nicht schon in der Lizenzgebühr berücksichtigt wurde; zu vermeiden ist nur eine Doppelentschädigung. Die drei Berechnungsarten dürfen aber nicht für denselben Schaden vermischt werden."],
                 merke="Die Lizenzgebühr ist das Minimum, nicht das Maximum des Schadensersatzes.",
                 level=3, concepts=["schadensersatz", "lizenzanalogie"], norms=["§ 14 Abs. 6", "Art. 13 DurchsetzungsRL"], cases=["eugh_liffers", "bgh_btk"], step="step:schema_durchsetzung.4.3"),
            fall("k14c-6", "Der Markthallenbetreiber",
                 "D hat die Prager Markthallen gemietet und vermietet die Stände an Einzelhändler weiter. Mehrere Händler verkaufen dort Fälschungen bekannter Modemarken; D wurde von den Markeninhabern darauf hingewiesen, unternimmt aber nichts. Die Inhaber beantragen eine gerichtliche Anordnung gegen D.",
                 "Kann gegen D als Vermieter eine Anordnung nach Art. 11 S. 3 DurchsetzungsRL ergehen?", True,
                 ["**Ja!** Wer Verkaufsflächen an Händler vermietet, die dort Fälschungen anbieten, ist **Mittelsperson, deren Dienste von einem Dritten zur Verletzung in Anspruch genommen werden** (EuGH Tommy Hilfiger/Delta Center, C-494/15). Es macht keinen Unterschied, ob der Marktplatz online (L'Oréal/eBay) oder physisch betrieben wird.",
                  "Die Anordnung setzt keine eigene Haftung des D voraus; Voraussetzungen und Verfahren regelt das nationale Recht (Erwägungsgrund 23). In Deutschland ist das die **Störerhaftung**: Unterlassungsanspruch aus § 14 Abs. 5 gegen den, der nach Hinweis auf eine klare Verletzung zumutbare Prüfpflichten verletzt (BGH Internet-Versteigerung II). Schadensersatz schuldet der Störer nicht."],
                 merke="Wer den Marktplatz stellt, muss nach Hinweis für Ordnung sorgen – ob online oder in der Halle.",
                 level=2, concepts=["mittelsperson_anordnung", "stoererhaftung"], norms=["§ 14 Abs. 5", "Art. 11 DurchsetzungsRL"], cases=["eugh_tommy_hilfiger", "bgh_internet_versteigerung_ii"], step="step:schema_durchsetzung.5"),
            fall("k14c-7", "Nur dieses eine Angebot?",
                 "Auf einer Online-Plattform bietet ein Händler Fälschungen von L'Oréal-Parfums an. Nach Hinweis sperrt der Plattformbetreiber das gemeldete Angebot, lehnt es aber ab, Vorkehrungen gegen gleichartige neue Angebote desselben Händlers zu treffen: Die Richtlinie verlange nur die Beendigung der konkreten Verletzung.",
                 "Muss die Anordnung gegen die Mittelsperson auch künftige gleichartige Verletzungen erfassen?", True,
                 ["**Ja!** Nach Art. 11 S. 3 DurchsetzungsRL müssen die Gerichte dem Betreiber Maßnahmen aufgeben können, die nicht nur die bestehende Verletzung beenden, sondern auch **neuen Verletzungen dieser Art vorbeugen** (EuGH L'Oréal/eBay, C-324/09). Die Maßnahmen müssen wirksam, verhältnismäßig und abschreckend sein (Art. 3 Abs. 2), etwa Sperrung des Nutzerkontos und Erleichterung der Identifizierung.",
                  "Grenze: keine allgemeine, aktive Überwachungspflicht aller Angebote und keine Schranken für den rechtmäßigen Handel. Der BGH verlangt entsprechend, dass der Betreiber nach Hinweis auch gleichartige künftige Verletzungen verhindert, soweit zumutbar (Internet-Versteigerung II, Kinderhochstühle im Internet)."],
                 merke="Sperren reicht nicht – die Anordnung gegen den Vermittler ist in die Zukunft gerichtet.",
                 level=2, concepts=["mittelsperson_anordnung", "stoererhaftung"], norms=["§ 14 Abs. 5", "Art. 11 DurchsetzungsRL", "Art. 3 DurchsetzungsRL"], cases=["eugh_loreal_ebay", "bgh_internet_versteigerung_ii", "bgh_kinderhochstuehle"], step="step:schema_durchsetzung.5"),
            fall("k14c-8", "Die Patentanwältin im Markenprozess",
                 "Die Universität Heidelberg klagt aus ihren Unionsmarken gegen NovaText; das Verfahren endet durch Vergleich, nach dem NovaText die Kosten trägt. Neben dem Rechtsanwalt hat eine Patentanwältin mitgewirkt. Im Kostenfestsetzungsverfahren verlangt die Universität deren Gebühren nach § 140 Abs. 4 MarkenG (damals Abs. 3). NovaText wendet ein, die Mitwirkung sei überflüssig gewesen; die Universität meint, darauf komme es nach dem Gesetzeswortlaut nicht an.",
                 "Sind die Patentanwaltskosten ohne Prüfung ihrer Notwendigkeit zu erstatten?", False,
                 ["**Nein!** Art. 3 und 14 DurchsetzungsRL verlangen, dass nur **zumutbare und angemessene** Kosten erstattet werden und das Gericht dies im Einzelfall prüfen kann. Eine Regelung oder Auslegung, nach der Patentanwaltskosten in Kennzeichenstreitsachen stets erstattungsfähig sind, verstößt dagegen (EuGH NovaText, C-531/20).",
                  "Der BGH legt § 140 Abs. 4 seither richtlinienkonform aus: Erstattung nur, wenn die Mitwirkung des Patentanwalts zur **zweckentsprechenden Rechtsverfolgung notwendig** war, was die Partei darlegen und glaubhaft machen muss (Kosten des Patentanwalts VII, I ZB 59/19). Dieselbe Frage stellt sich bei § 143 Abs. 3 PatG, § 27 Abs. 3 GebrMG und § 52 Abs. 4 DesignG."],
                 merke="§ 140 Abs. 4 ist kein Automatismus mehr: Notwendigkeit der patentanwaltlichen Mitwirkung prüfen.",
                 level=2, concepts=["prozesskosten_erstattung", "richtlinienkonforme_auslegung"], norms=["§ 140 Abs. 4", "Art. 14 DurchsetzungsRL", "Art. 3 DurchsetzungsRL"], cases=["eugh_novatext", "bgh_kosten_patentanwalt_vii"], step="step:schema_durchsetzung.6"),
            mc("k14c-9", "Abmahnkosten und Art. 14",
               "Ein Privatmann hat ein Computerspiel in einer Tauschbörse angeboten und wird vom Rechtsinhaber anwaltlich abgemahnt. § 97a Abs. 3 UrhG begrenzt den Gegenstandswert für die Anwaltsgebühren gegenüber Privatpersonen auf 1.000 Euro, es sei denn, das ist im Einzelfall unbillig. Welche Aussage trifft zu?",
               ["Abmahnkosten fallen nicht unter Art. 14 DurchsetzungsRL, weil sie außergerichtlich entstehen", "Abmahnkosten sind „sonstige Kosten“ im Sinne von Art. 14; die Deckelung ist zulässig, weil die Unbilligkeitsklausel dem Gericht erlaubt, Verhältnismäßigkeit und Billigkeit im Einzelfall zu wahren", "Die Deckelung verstößt gegen Art. 14, weil der Obsiegende stets alle Kosten erstattet bekommen muss", "Art. 14 gilt nur für Patentstreitigkeiten"], 1,
               ["Der EuGH ordnet die Kosten der außergerichtlichen Rechtsverfolgung, insbesondere einer anwaltlichen Abmahnung, als **„sonstige Kosten“** im Sinne von Art. 14 ein. Eine pauschale Deckelung ist mit Art. 14 vereinbar, wenn sie dem Gericht Raum lässt, in Fällen der Unbilligkeit abzuweichen (Koch Media, C-559/20). Schon zuvor hatte er Pauschaltarife gebilligt, sofern ein erheblicher und angemessener Teil der Kosten erstattet wird (United Video Properties, C-57/15).",
                "Im Markenrecht gibt es keine Deckelung; Abmahnkosten werden aus Geschäftsführung ohne Auftrag (§§ 677, 683, 670 BGB) oder als Schadensersatz (§ 14 Abs. 6) ersetzt, begrenzt auf das Erforderliche."],
               level=3, concepts=["prozesskosten_erstattung"], norms=["Art. 14 DurchsetzungsRL", "§ 14 Abs. 6"], cases=["eugh_koch_media", "eugh_united_video"], step="step:schema_durchsetzung.6"),
            fall("k14c-10", "Das Urteil in der Zeitung",
                 "K hat gegen V ein Urteil wegen Markenverletzung erstritten; das Urteil spricht K die Befugnis zu, es auf Kosten von V in einer Fachzeitschrift zu veröffentlichen. Das Urteil wird am 1. März rechtskräftig. K lässt sich Zeit und will die Anzeige am 15. Juli schalten.",
                 "Kann K die Veröffentlichung noch auf Kosten von V vornehmen?", False,
                 ["**Nein!** Die Befugnis zur Urteilsbekanntmachung nach § 19c erlischt, wenn von ihr nicht **innerhalb von drei Monaten nach Eintritt der Rechtskraft** Gebrauch gemacht wird (§ 19c S. 3). Am 15. Juli ist die Frist seit dem 1. Juni abgelaufen; K kann auf eigene Kosten veröffentlichen, aber nicht mehr auf Kosten von V.",
                  "§ 19c setzt Art. 15 DurchsetzungsRL um (Verbreitung der Entscheidung auf Kosten des Verletzers, Erwägungsgrund 27: Abschreckung und Aufklärung). Voraussetzung ist ein berechtigtes Interesse; Art und Umfang bestimmt das Urteil; der Ausspruch ist nicht vorläufig vollstreckbar (S. 4). Wortgleich: § 140e PatG, § 24e GebrMG, § 47 DesignG, § 103 UrhG."],
                 merke="Urteilsbekanntmachung: berechtigtes Interesse, drei Monate ab Rechtskraft, sonst verfallen.",
                 level=1, concepts=["urteilsbekanntmachung"], norms=["§ 19c", "Art. 15 DurchsetzungsRL"], step="step:schema_durchsetzung.4.4"),
            mc("k14c-11", "Strafrecht als Sanktion",
               "Welche Aussage zum Verhältnis von Durchsetzungsrichtlinie und Strafrecht ist richtig?",
               ["Die Richtlinie verpflichtet die Mitgliedstaaten, Markenverletzungen mit Freiheitsstrafe zu bedrohen", "Die Richtlinie regelt nur zivil- und verwaltungsrechtliche Maßnahmen; Strafvorschriften wie § 143 MarkenG bleiben nach Art. 2 Abs. 3 lit. c und Art. 16 unberührt und zulässig", "Die Richtlinie verbietet strafrechtliche Sanktionen, weil sie unverhältnismäßig sind", "Strafrechtliche Sanktionen sind in Art. 13 abschließend geregelt"], 1,
               ["Die Richtlinie betrifft die **zivil- und verwaltungsrechtlichen** Maßnahmen, Verfahren und Rechtsbehelfe. Innerstaatliche Vorschriften über strafrechtliche Verfahren und Strafen bleiben unberührt (Art. 2 Abs. 3 lit. c), und Art. 16 stellt klar, dass die Mitgliedstaaten daneben „andere angemessene Sanktionen“ vorsehen können. Ein Vorschlag für eine strafrechtliche Richtlinie („IPRED 2“) scheiterte.",
                "Deutschland: § 143 MarkenG (Freiheitsstrafe bis drei Jahre, gewerbsmäßig bis fünf Jahre, Antragsdelikt), § 143a (Unionsmarke), § 144 (geographische Herkunftsangaben); dazu die Grenzbeschlagnahme nach der VO (EU) Nr. 608/2013 und subsidiär §§ 146 ff. MarkenG."],
               level=2, concepts=["durchsetzungsrl", "transit"], norms=["Art. 16 DurchsetzungsRL", "Art. 2 DurchsetzungsRL", "§ 143", "§ 146"]),
        ]),
    ],
)
